window.MONSTER_CHUNK_52 = [{"name":"Swan Maiden","cr":6,"xp":2400,"alignment":"CG","size":"Medium","type":"fey","subtypes":["shapechanger"],"init":5,"senses":[{"type":"low-light vision"}],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+4 armor, +4 Dex, +1 dodge, +1 natural","hp":55,"hd":"10d6+20","hdvalue":10,"fort":5,"ref":12,"will":8,"dr":"5/cold iron","resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"sr":17,"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"mwk rapier +11 (1d6+1/18-20)","ranged":"longbow +10 (1d8/x3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"}]},{"frequency":"1/day","spells":[{"spell":"confusion"},{"spell":"deep slumber"},{"spell":"entangle"},{"spell":"glitterdust"},{"spell":"major image"}]}],"strength":13,"dexterity":20,"constitution":15,"intelligence":10,"wisdom":12,"charisma":15,"baseatk":5,"cmb":10,"cmd":22,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Bluff","value":10},{"skill":"Fly","value":20},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":20}],"languages":["Common","Sylvan"],"sq":[{"type":"change shape","details":"trumpeter swan, beast shape I"},{"type":"feather cloak"},{"type":"trackless step"},{"type":"transformation ritual"}],"environments":["temperate lakes","temperate swamps"],"organizations":["solitary","pair","flock (3-10)"],"treasure":"standard (chain shirt, mwk longsword, longbow with 20 arrows)","description_visual":"This tall, regal woman is clad in a long cloak of pristine white swan feathers and silvery armor with a winged helm.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Feather Cloak","kind":"Su","details":"Without her feather cloak, a swan maiden can't use her change shape ability."},{"type":"Transformation Ritual","kind":"Su","details":"A swan maiden can transform a willing good female humanoid into a swan maiden via a ritual that takes 24 hours. The humanoid loses her class and racial abilities."}],"description":"Swan maidens are fey shapechangers who vow to protect unspoiled wilds from the encroachment of civilization or evil. They live in small flocks along secluded lakeshores. Because stealing a swan maiden's cloak robs her of her shapechanging ability, most maidens avoid humanoids and take up armor and weapons to defend themselves.","ecology":"","habitat_society":""},{"name":"Tear of Nuruu'gal","cr":6,"xp":2400,"alignment":"CN","size":"Small","type":"ooze","subtypes":["fire"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":6,"ac_touch":6,"ac_flat_footed":6,"ac_mods":"-5 Dex, +1 size","hp":62,"hd":"5d8+40","hdvalue":5,"fort":8,"ref":-4,"will":1,"dr":"5/-","immunities":["fire","ooze traits"],"sr":17,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"slam +7 (1d6+3 plus burn and grab)","ranged":"ranged touch -1 (by spell)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d6, DC 19"},{"type":"constrict","details":"1d6+3"},{"type":"symbiosis"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect thoughts"},{"spell":"produce flame"}]},{"frequency":"3/day","spells":[{"spell":"searing light"}]}],"strength":14,"dexterity":1,"constitution":24,"intelligence":4,"wisdom":5,"charisma":1,"baseatk":3,"cmb":4,"cmb_special":"+4 vs. grapple","cmd":9,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (symbiosis)"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Stealth","value":2}],"languages":["telepathy 100 ft."],"environments":["any land"],"organizations":["solitary","pack (2-6)"],"treasure":"none","description_visual":"A slithering blob of amoeba-like protoplasm shines with flame, warping the air around it in a searing mirage.","source":"Lost Cities Of Golarion","special_abilities":[{"type":"Symbiosis","kind":"Ex","details":"As part of a constrict attack, a tear of Nuruu'gal can attempt to forcefully inhabit a humanoid victim's body. A DC 21 Fortitude save resists this intrusion and renders immunity to that ooze's symbiosis ability for 24 hours; failure means the ooze spends a full-round action inhabiting its new host. Once absorbed, the ooze grants incredible boons to willing hosts, or slowly incinerates unwilling victims. A willing host ceases aging, is sustained as if wearing a ring of sustenance, and becomes sterile. He or she also gains the fire subtype, spell resistance, and telepathic abilities of the tear of Nuruu'gal. A host can use the creature's spell-like abilities, with save DCs calculated using the host's Hit Dice and Charisma score, although daily limits of powers still apply. Damage dealt to the host body doesn't harm the ooze. Unwilling victims are granted no abilities, and are instead tortured with searing pain. Victims take automatic burn damage each round, and must succeed on a DC 21 Fortitude save or become nauseated for 1d4 rounds. While this occurs, the ooze may telepathically appeal to the host for control of the body to prevent further pain (treat control as magic jar, with no receptacle required). The ooze may vacate the body of a host as a full-round action, bursting forth in a protoplasmic expulsion, dealing double burn damage. A victim may attempt to expel the creature from his or her body as a full-round action with a DC 21 Fortitude save, but each attempt results in automatic burn damage from the ooze, and damage from the creature's violent exit if successful (as if the ooze had left voluntarily). Remove curse expels the creature, if the caster succeeds on a DC 21 caster level check. The save DCs are Constitution-based."}],"description":"First spawned by the primordial godling Nuruu'gal in the lost Azlanti city of Nal-Vashkin, these fiery, parasitic oozes contain a portion of the creature's essence and foul sentience. The oozes hunt ceaselessly, seeking to force their amoebic protoplasm into the bodies of humanoids to turn their hosts to the service of their master, whether the hosts are willing or not. After many years of possession, the host and the symbiote may undergo a strange metamorphosis, exploding into a horrible light that catalyzes into a being known as a shining child.","ecology":"","habitat_society":""},{"name":"Tekenu","cr":6,"xp":2400,"alignment":"NE","size":"Small","type":"undead","init":8,"senses":[{"type":"lifesense"}],"ac":16,"ac_touch":16,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 dodge, +1 size","hp":65,"hd":"10d8+20","hdvalue":10,"fort":5,"ref":7,"will":17,"defensive_abilities":["odd anatomy"],"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to channeled energy"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":30,"maneuverability":"poor"}],"melee":"2 slams +12 (2d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"canopic consumption"},{"type":"distraction","details":"DC 18"}],"strength":11,"dexterity":19,"intelligence":2,"wisdom":10,"charisma":15,"baseatk":7,"cmb":24,"cmd":38,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":6},{"skill":"Stealth","value":15}],"environments":["warm ruins"],"organizations":["solitary","pair","stewardship (3-5)"],"treasure":"none","description_visual":"A collection of cast-off organs rolls and squeezes against itself, forming a writhing mass of viscera that hovers in the air.","source":"AP 80","special_abilities":[{"type":"Canopic Consumption","kind":"Su","details":"As a full-round action, a tekenu can consume a single organ from the body of a helpless or recently dead humanoid or monstrous humanoid. This organ must either be magically preserved or come from a creature that is alive or has been dead no longer than 3 days. Only one organ may be harvested from each body; all others are destroyed in the process as the tekenu rips the body apart. Each organ consumed grants the tekenu a unique ability listed below. When discovered, a tekenu typically has 1d4 of the following abilities, each corresponding to the most recent organs the creature absorbed. Even when the creature has absorbed all four organs (thus gaining a full suite of abilities), it still hungers for more. The challenge rating of a tekenu that possesses all four canopic organs increases by 1. Intestines: The tekenu gains the grab ability when using its slam attacks. A tekenu can grapple Medium or smaller creatures with this attack, and it gains a +2 racial bonus on its CMB and to its CMD. In addition, the tekenu gains the constrict ability, dealing 2d6 points of damage. Liver: The tekenu's slam attacks deal 1d3 points of Constitution damage to any living creature that fails a DC 17 Fortitude save. This is a poison effect, and the save DC is Charisma-based. Lungs: As a standard action, the tekenu can expel most of the air and moisture from its form, turning into a pile of desiccated viscera. While in this form, the tekenu gains a +8 racial bonus on Stealth checks, and its fly speed increases to 60 ft. with good maneuverability. It can revert to its normal form as a free action. Stomach: The tekenu deals an additional 1d6 points of acid damage with its slam attacks."},{"type":"Odd Anatomy","kind":"Ex","details":"As a collection of various individual organs and flesh, a tekenu is in many ways similar to a swarm. The creature isn't subject to critical hits or flanking, and it is immune to any spell or effect that targets a specific number of creatures (including single-target spells such as disintegrate)."},{"type":"Vulnerable to Channeled Energy","kind":"Ex","details":"A tekenu takes 150% as much damage as normal from channeled positive energy."}],"description":"Guardians of long-abandoned tombs, tekenu are the result of a vile practice that instills the discarded piles of flesh left over from the mummification process with an unholy awareness. Separated from the sacred organs placed in canopic jars, tekenus attempt to reconnect with their counterparts among the living by killing creatures so that they can absorb intestines, livers, lungs, and stomachs into their squirming\n\nforms-a process that grants the undead creature additional powers.\n\nTekenus have been known to hide inside canopic jars collected from excavations (cleverly pulling the lid closed), attacking passersby like a trapdoor spider. Adventurers searching through lost reliquaries and tombs of ancient Osirion commonly call these foul creatures \"gutswarms\"; however, the name scholars give them is derived from an ancient Osirian term for the cast off remains of mummification rituals. A tekenu has an ever-changing form roughly 3 ft. long and 2 ft. wide, essentially the size of a robust humanoid's torso and abdomen. The mass weighs about 40 pounds.\n\nEcology\n\nScholars debate the genesis of the tekenu. Some propose these atrocities are the creations of sects of evil priests in ancient Osirion, as they have been encountered only in tombs in that nation and of that era. However, several groups claim responsibility for the creation of the tekenu, including modern cults of Kabriri and Urgathoa. More cautious and traditional scholars claim that the tekenu are instead undead abominations resulting from improperly conducted mummification rituals, specifically ones in which the incision to remove organs was performed by a criminal or laborer.\n\nThe viscera that constitute a tekenu make it less susceptible to weapon damage and provide it with defensive abilities similar to those of swarms. In fact, until a tekenu absorbs one of the sacred canopic organs, it poses no stronger a threat than that of a swarm of Tiny vermin. The absorption of a sacred organ, however, prompts a radical transformation in the tekenu. Only fresh organs or those preserved by magic enhance the tekenu in this way. Unearthed tekenu have typically consumed one or two organs, normally those belonging to laborers trapped in the tomb at the time it was sealed.\n\nIntestines merge with the discarded remnants to act as long, rope-like appendages, which the tekenu uses to snag and pummel prey. Consuming a liver allows the tekenu to poison its victims and wither their bodies. A set of lungs gives the swarm the ability to hide as a pile of dried gore and increases its mobility. When the tekenu consumes a stomach, its attacks carry a digestive acid to help break down their victims. Of these organs, the tekenu shows particular affinity for absorbing the lungs first, as most adventurers discover a tekenu after being deceived by desiccated viscera they assume to be harmless.\n\nHabitat & Society\n\nCreated in ritual chambers and tombs, most tekenus have no choice of where they are found. Only the most perverse of ancient nobility would have tekenu present\n\nin their final resting places. In the most heinous of cases, tekenu would be stealthily placed into a resting chamber immediately prior to the tomb's sealing. This serves as a final insult to the dead, leaving the undead abomination to break into the holy canopic jars and consume the vital organs within while they were still fresh enough to bestow power. In cases where a tekenu was used as a guardian, a fifth jar was placed inside the tomb to house it.\n\nIn some cases, either because the canopic jars were exceptionally sealed or because they were absent altogether, a tekenu may have none of the abilities granted by its canopic consumption ability. Once its tomb prison is breached (by explorers or some natural calamity), the tekenu becomes a roaming hunter, leaving its lair in search of fresh organs to consume. Acting on base instinct, the creature hunts until it successfully absorbs all four required organs. Upon gathering these absent parts, the tekenu then moves back to the tomb of its creation, where it dutifully guards the site from future intruders. Although a tekenu is barely intelligent, it is drawn to the site of its creation, a lingering result of the ritual that created it.\n\nA tekenu has no ability to communicate or interact, and its thoughts, if read by some form of magic, are simple and instinctual. As it preys upon only living and recently dead creatures, it often overlooks constructs and undead. Rare necropolises can be found filled with larger groups of these undead creatures, sealed away in remote chambers or allowed to wander the greater complex unopposed. These groups of tekenus-given stewardships by the priests of Ancient Osirion-ignore other tomb guardians, provided they are not living creatures. These tekenus are set to roam the necropolis consuming small rodents and vermin in the same manner a wizard might use an acidic ooze to dispose of waste.","ecology":"Scholars debate the genesis of the tekenu. Some propose these atrocities are the creations of sects of evil priests in ancient Osirion, as they have been encountered only in tombs in that nation and of that era. However, several groups claim responsibility for the creation of the tekenu, including modern cults of Kabriri and Urgathoa. More cautious and traditional scholars claim that the tekenu are instead undead abominations resulting from improperly conducted mummification rituals, specifically ones in which the incision to remove organs was performed by a criminal or laborer.\n\nThe viscera that constitute a tekenu make it less susceptible to weapon damage and provide it with defensive abilities similar to those of swarms. In fact, until a tekenu absorbs one of the sacred canopic organs, it poses no stronger a threat than that of a swarm of Tiny vermin. The absorption of a sacred organ, however, prompts a radical transformation in the tekenu. Only fresh organs or those preserved by magic enhance the tekenu in this way. Unearthed tekenu have typically consumed one or two organs, normally those belonging to laborers trapped in the tomb at the time it was sealed.\n\nIntestines merge with the discarded remnants to act as long, rope-like appendages, which the tekenu uses to snag and pummel prey. Consuming a liver allows the tekenu to poison its victims and wither their bodies. A set of lungs gives the swarm the ability to hide as a pile of dried gore and increases its mobility. When the tekenu consumes a stomach, its attacks carry a digestive acid to help break down their victims. Of these organs, the tekenu shows particular affinity for absorbing the lungs first, as most adventurers discover a tekenu after being deceived by desiccated viscera they assume to be harmless.","habitat_society":"Created in ritual chambers and tombs, most tekenus have no choice of where they are found. Only the most perverse of ancient nobility would have tekenu present\n\nin their final resting places. In the most heinous of cases, tekenu would be stealthily placed into a resting chamber immediately prior to the tomb's sealing. This serves as a final insult to the dead, leaving the undead abomination to break into the holy canopic jars and consume the vital organs within while they were still fresh enough to bestow power. In cases where a tekenu was used as a guardian, a fifth jar was placed inside the tomb to house it.\n\nIn some cases, either because the canopic jars were exceptionally sealed or because they were absent altogether, a tekenu may have none of the abilities granted by its canopic consumption ability. Once its tomb prison is breached (by explorers or some natural calamity), the tekenu becomes a roaming hunter, leaving its lair in search of fresh organs to consume. Acting on base instinct, the creature hunts until it successfully absorbs all four required organs. Upon gathering these absent parts, the tekenu then moves back to the tomb of its creation, where it dutifully guards the site from future intruders. Although a tekenu is barely intelligent, it is drawn to the site of its creation, a lingering result of the ritual that created it.\n\nA tekenu has no ability to communicate or interact, and its thoughts, if read by some form of magic, are simple and instinctual. As it preys upon only living and recently dead creatures, it often overlooks constructs and undead. Rare necropolises can be found filled with larger groups of these undead creatures, sealed away in remote chambers or allowed to wander the greater complex unopposed. These groups of tekenus-given stewardships by the priests of Ancient Osirion-ignore other tomb guardians, provided they are not living creatures. These tekenus are set to roam the necropolis consuming small rodents and vermin in the same manner a wizard might use an acidic ooze to dispose of waste."},{"name":"Tendriculos","cr":6,"xp":2400,"alignment":"N","size":"Huge","type":"plant","init":3,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"-1 Dex, +12 natural, -2 size","hp":76,"hd":"9d8+36","hdvalue":9,"hp_mods":["regeneration 10 (bludgeoning or fire)"],"fort":10,"ref":4,"will":9,"immunities":["acid","plant traits"],"speed":[{"type":"land","speed":20}],"melee":"bite +11 (2d6+7 plus grab), 2 tentacles +6 (1d6+3 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"paralysis","details":"3d6 rounds, DC 18"},{"type":"swallow whole","details":"2d6 acid damage plus paralysis, AC 15, 7 hp"}],"strength":24,"dexterity":9,"constitution":18,"intelligence":3,"wisdom":8,"charisma":3,"baseatk":6,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":24,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":1,"special":"+9 in undergrowth"}],"languages":["Sylvan (cannot speak)"],"environments":["temperate forests","warm forests"],"organizations":["solitary","pair","grove (3-6)"],"treasure":"standard","description_visual":"This plant's thick trunk is capped by a crown of wide leaves, whipping vines, mushrooms, and a ravenous purple maw.","source":"PFRPG Bestiary 2","description":"A tendriculos is a creature brought into being through a corruption of nature, often where foul magic has seeped into the environs for many years, or where the boundaries between the Material Plane and the mysterious realm of the fey have worn thin. Tales and myths speak of arcane manipulation from other planes, while others speak of a tendriculos as being the manifestation of an angered spirit of nature.\n\nA voracious carnivore, the tendriculos is an active hunter when it needs to be but it prefers to rely on ambush tactics, choosing welltraveled areas in the forest where it can lie in wait in the undergrowth. The creature is quick to swallow any prey it happens to catch in its vines, relying upon the acidfilled reservoir in its trunk to finish off prey that may still have a bit of fight left in it. This acid not only consumes organic material with shocking ease, but also contains a powerful paralytic enzyme that further reduces a creature's chance of escape once it's been gulped down by the plant.\n\nAlthough incapable of speech itself, the tendriculos generally understands a handful of words in a single language (usually Sylvan). While they tend to see all smaller creatures as nothing more than food, tales exist of certain creatures, particularly fey or druids, having secured a sort of alliance with local tendriculoses. In such cases, the tendriculos is more than willing to serve its ally as a guardian, so long as the ally is diligent at providing the plant with a regular supply of food.\n\nThe fact that a tendriculos displays a curious mix of plant, fungal, and even animal traits (in the form of its almost fleshy, toothed maw) has long intrigued sages.\n\nThat the creature is a plant is firmly established, yet it lays egg-like spheres when the need to reproduce strikes.\n\nThese \"eggs\" are in fact massive, puff ball-like fungi filled with spores-when jostled, the cloud of spores that is released can carry for miles, ensuring that a single tendriculos can seed a huge territory.\n\nA tendriculos is 20 ft. tall and weighs 3,500 pounds.","ecology":"","habitat_society":""},{"name":"Terra-Cotta Soldier","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"construct","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":64,"hd":"8d10+20","hdvalue":8,"fort":2,"ref":5,"will":10,"dr":"5/bludgeoning","immunities":["construct traits","fire"],"sr":17,"speed":[{"type":"land","speed":30}],"melee":"longsword +10 (1d8+3/19-20), short sword +10 (1d6+1/19-20) or  2 slams +11 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"keen weapons"},{"type":"rank fighting"}],"strength":16,"dexterity":16,"intelligence":1,"wisdom":11,"charisma":1,"baseatk":8,"cmb":18,"cmb_special":"+8 vs. grapple","cmd":33,"feats":[{"feat":"Improved Initiative"},{"feat":"Two Weapon Fighting"},{"feat":"Weapon Focus (longsword, shortsword)"}],"skills":[{"skill":"Perception","value":8}],"environments":["any"],"organizations":["solitary","troop (3-12)","army (13+)"],"treasure":"incidental (longsword, short sword)","description_visual":"This perfectly sculpted, finely detailed, life-sized clay figure has a look of fierce determination and a sword clenched in each hand.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Keen Weapons","kind":"Su","details":"After it has engaged in at least 1 round of combat, a terra-cotta soldier's weapons automatically gain the benefits of keen weapon (CL 6th). This effect persists until the end of the battle."},{"type":"Rank Fighting","kind":"Ex","details":"Whenever a terra-cotta soldier is adjacent to another terra-cotta soldier, it gains a +2 dodge bonus to its AC and a +2 bonus on saving throws, attack rolls, and damage rolls."}],"description":"A terra-cotta soldier is crafted from clay and fired into ceramic, and is usually sculpted to resemble an armored human soldier, although terra-cotta soldiers resembling other races, such as hobgoblins, tengus, or even demons and oni, are also common. Terra-cotta soldiers are often created to guard the tomb of powerful rulers, standing in silent ranks to guard their liege even after his or her death. These soldiers stand vigil for centuries, animating only to defend the tomb and its riches from tomb robbers. Terra-cotta soldiers are typically painted with colored lacquer, though this decoration is often worn away from use or faded with age. A terra-cotta soldier stands 6 ft. tall and weighs 600 pounds.\n\nUnlike most constructs, a terra-cotta soldier carries within its form a spark of intelligence. This is hardly enough to grant the construct the ability to speak or otherwise engage in free will, but it is enough for it to carry out more complex tactics than most constructs are capable of. It's not unusual for a terra-cotta soldier to possess different feats or use different weapons. Two relatively common variants are summarized below.\n\nTerra-Cotta Archer (+0 CR): Terra-cotta archers are simply terra-cotta soldiers outfitted with composite longbows. Terra-cotta archers have Improved Initiative, Point-Blank Shot, Precise Shot, and Weapon Focus (longbow) as feats.\n\nTerra-Cotta Horseman (+1 CR): Some terra-cotta soldiers are crafted to resemble warriors mounted on terra-cotta horses, though rider and mount are one creature. Terra-cotta horsemen are Large terra-cotta soldiers with 10 racial Hit Dice and the trample and undersized weapons special abilities. Terra-cotta horsemen are usually outfitted with lances instead of swords, and have Improved Bull Rush, Improved Initiative, Improved Overrun, Power Attack, and Weapon Focus (lance) as feats.\n\nConstruction\n\nA terra-cotta soldier's body is made from 600 pounds of clay, fired with rare and magical glazes worth 500 gp.\n\nTERRA-COTTA SOLDIER\n\nCL 9th; Price 19,500 gp\n\nConstruction\n\nRequirements Craft Construct, animate objects, cat's grace, geas/ quest, keen edge, creator must be caster level 9th; Skill Craft (pottery) or Craft (sculptures) DC 14; Cost 10,000 gp","ecology":"","habitat_society":""},{"name":"Thriae Dancer","cr":6,"xp":2400,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":60,"hd":"8d10+16","hdvalue":8,"fort":6,"ref":9,"will":21,"save_mods":"+4 vs. mind-affecting effects","immunities":["poison","sonic"],"resists":[{"type":"acid","value":10}],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"mwk glaive +12 (1d10+3/x3), sting +10 (1d8+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"inspiring dance"},{"type":"poison"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect secret doors"}]},{"frequency":"at-will","spells":[{"spell":"lullaby"}]},{"frequency":"1/day","spells":[{"spell":"deep slumber"},{"spell":"suggestion"}]},{"frequency":"3/day","spells":[{"spell":"calm emotions"},{"spell":"charm person"},{"spell":"hypnotism"}]}],"strength":15,"dexterity":16,"constitution":15,"intelligence":12,"wisdom":13,"charisma":16,"baseatk":8,"cmb":36,"cmd":46,"feats":[{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (glaive)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Diplomacy","value":11},{"skill":"Fly","value":11},{"skill":"Perception","value":10},{"skill":"Perform (dance)","value":11},{"skill":"Sleight of Hand","value":6},{"skill":"Stealth","value":12}],"languages":["Common","Thriae"],"environments":["any"],"organizations":["solitary","duet","trio","troupe (4-8)"],"treasure":"standard (mwk glaive, 3 doses of merope)","description_visual":"This elegant half-woman, half-bee wields a glaive and is clad in flowing, gauzy garments. A veil covers most of her face, revealing only seductive, unnaturally beautiful eyes.","group":"Thriae","source":"AP 81","special_abilities":[{"type":"Inspiring Dance","kind":"Su","details":"Three times per day as a standard action, a thriae dancer can consume a dose of merope (honey from the thriae queen) to channel her connection to the natural world into an awe-inspiring dance. This dance may have a variety of effects depending on which of the following performances she chooses. Once she has begun, the thriae dancer may maintain her dance as a free action, and the effects of the dance persist as long as the thriae performs her dance. A thriae dancer can dance for a number of rounds equal to her Hit Dice before becoming fatigued. After that, if she continues dancing for that same number of rounds, she becomes exhausted. A thriae dancer may switch between performances as a swift action. Targets must be within 60 ft. and able to see the thriae dancer in order to be affected by her dance. This is a mind-affecting effect. Dance of Fervor: This performance affects all non-thriae creatures within its range with the effects of both confusion and rage (Will DC 17 negates). When this effect ends, affected creatures are fatigued for a number of rounds equal to the length of time they were affected by the dance of fervor. A creature may not be affected by the same thriae dancer's dance of fervor more than once in 24 hours. The save DC is Charisma-based. Dance of Grace: This performance grants all thriae within its range (including the dancer) a +1 insight bonus to AC and on Reflex saving throws. This bonus increases to +2 if three or more thriae dancers are performing a dance of grace within range of the target. Dance of Passion: This performance grants all thriae within its range (including the dancer) a +1 insight bonus on attack and damage rolls. This bonus increases to +2 if three or more thriae dancers are performing a dance of passion within range of the target."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d3 Str; cure 1 save."}],"description":"For as stoic and pragmatic as the thriae may be, they do appreciate art, grace, and beauty. This is exemplified not only by their ornately crafted weapons, armor, and jewelry, but also by their renowned dancers. These talented individuals are the most honored performers of their race, and they grace the halls and temple chambers of every thriae colony.\n\nWhile all thriae can be considered the epitome of alien grace and charm, thriae dancers are always among the most beautiful of their kind. They are typically 6 ft. tall and weigh 140 pounds.\n\nEcology\n\nOther races may scoff at the fact that thriae dancers seemingly rely on merope consumption in order to channel their mystical power into their dances, but there is much more to this act than one might realize. A thriae dancer's reliance on merope to execute her awesome performances is akin to a ballerina's reliance on her specialized shoes-while a ballet can be performed without them, the final result lacks a certain amount of finish without this integral element. So too does a thriae dancer's use of merope enhance her performance, with the potent serum pushing her body to its utmost limits. As the merope courses through a dancer, she channels her mysterious art into a spiritual energy capable of thrusting viewers to previously unknown heights of pleasure, awe, and sorrow. It's true that thriae are a stoic, nigh-unf linching race, but in the middle of a thriae dancer's performance, it's rare to see any thriae witnesses unmoved by such a powerful spectacle.\n\nHabitat & Society\n\nLike all thriae, a dancer's role in the colony is chosen for her during adolescence, and she's thereafter cared for and trained by elder members from the same occupation until ready to perform on her own. A dancer's training takes many years of concentrated effort and tutelage from her superiors, during which time she's permitted to see no one but her fellow dancers. Thriae seers reason that dancers must be completely virginal in order for them to channel only the purest forms of nature's secrets. All training takes place within a special temple room in the thriae colony, where incense derived from merope is burned constantly to ensure the dancers' focus is sustained for hours on end.\n\nDancers train in troupes, and most performances are choreographed group pieces performed once a month in the colony's largest hall, with an audience of thriae from all parts of the colony and caste system. The buzz of wings and even the sound of twitching antennae become muted as thriae soldiers, seers, and workers eagerly witness the highly spiritual dance ceremony.\n\nDrones-those humanoid men inducted into thriae society-are not permitted to witness thriae dances, as to behold such beauty would surely drive them irreparably mad.\n\nOnly the most talented and coveted thriae dancers are permitted to perform alone-there's typically only one such dancer in the entire colony, though some colonies might host a pair of honored performers. The solo or duet performances of these honored individuals are considered sacred affairs, and are typically attended only by the queen and upper class thriae such as seers, royal consorts, and generals. Venerated by their peers, these dancers are known as thriae terpsichoreans, and occupy the upper echelons of thriae society. Thriae terpsichoreans typically have levels in bard, are at least CR 9, and have access to the following spell-like abilities: 3/day-heroism, suggestion; 1/ day-zone of silence.","ecology":"Other races may scoff at the fact that thriae dancers seemingly rely on merope consumption in order to channel their mystical power into their dances, but there is much more to this act than one might realize. A thriae dancer's reliance on merope to execute her awesome performances is akin to a ballerina's reliance on her specialized shoes-while a ballet can be performed without them, the final result lacks a certain amount of finish without this integral element. So too does a thriae dancer's use of merope enhance her performance, with the potent serum pushing her body to its utmost limits. As the merope courses through a dancer, she channels her mysterious art into a spiritual energy capable of thrusting viewers to previously unknown heights of pleasure, awe, and sorrow. It's true that thriae are a stoic, nigh-unf linching race, but in the middle of a thriae dancer's performance, it's rare to see any thriae witnesses unmoved by such a powerful spectacle.","habitat_society":"Like all thriae, a dancer's role in the colony is chosen for her during adolescence, and she's thereafter cared for and trained by elder members from the same occupation until ready to perform on her own. A dancer's training takes many years of concentrated effort and tutelage from her superiors, during which time she's permitted to see no one but her fellow dancers. Thriae seers reason that dancers must be completely virginal in order for them to channel only the purest forms of nature's secrets. All training takes place within a special temple room in the thriae colony, where incense derived from merope is burned constantly to ensure the dancers' focus is sustained for hours on end.\n\nDancers train in troupes, and most performances are choreographed group pieces performed once a month in the colony's largest hall, with an audience of thriae from all parts of the colony and caste system. The buzz of wings and even the sound of twitching antennae become muted as thriae soldiers, seers, and workers eagerly witness the highly spiritual dance ceremony.\n\nDrones-those humanoid men inducted into thriae society-are not permitted to witness thriae dances, as to behold such beauty would surely drive them irreparably mad.\n\nOnly the most talented and coveted thriae dancers are permitted to perform alone-there's typically only one such dancer in the entire colony, though some colonies might host a pair of honored performers. The solo or duet performances of these honored individuals are considered sacred affairs, and are typically attended only by the queen and upper class thriae such as seers, royal consorts, and generals. Venerated by their peers, these dancers are known as thriae terpsichoreans, and occupy the upper echelons of thriae society. Thriae terpsichoreans typically have levels in bard, are at least CR 9, and have access to the following spell-like abilities: 3/day-heroism, suggestion; 1/ day-zone of silence."},{"name":"Trench Zombie","cr":6,"xp":2400,"race":"Human","classes":[{"class":"fighter (trench fighter)","level":6}],"alignment":"LN","size":"Medium","type":"undead","subtypes":["augmented human","human"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 dodge, +3 natural","hp":43,"hd":"6d10 (+6)","hdvalue":6,"fort":4,"ref":6,"will":2,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2 channel resistance +4"],"dr":"5/ magic and slashing","immunities":["acid","cold","electricity","undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"socket bayonet +9 (1d6+3) or   slam +9 (1d6+4)","ranged":"Mosin-Nagant M1891 rifle +12 (1d10+6/x4) or   M1914 concussion grenade +10 (3d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"trench warfare","details":"rifle"},{"type":"weapon training","details":"firearms +1"}],"strength":17,"dexterity":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":6,"cmb":2,"cmd":14,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Toughness"},{"feat":"Weapon Focus (rifle)"},{"feat":"Weapon Specialization (rifle)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Craft (firearms)","value":4},{"skill":"Knowledge (engineering)","value":4},{"skill":"Perception","value":7},{"skill":"Profession (soldier)","value":5},{"skill":"Ride","value":8},{"skill":"Stealth","value":10},{"skill":"Survival","value":5}],"languages":["Russian"],"sq":[{"type":"symbiote"}],"environments":["any"],"organizations":["solitary","pair","horror (3-5)"],"treasure":"none","description_visual":"You see a rotting creature leaking sulfurous fumes from beneath its acid-burned, peeling skin, and bristling with the armaments it possessed in its horrifying death.","source":"AP 71","special_abilities":[{"type":"Trench Warfare","kind":"Ex","details":"Starting at 3rd level, a trench fighter can select one specific type of firearm (such as a machine gun, revolver, or rifle). He gains a bonus equal to his Dexterity modifier on damage rolls when firing that type of firearm. Every 4 levels thereafter (7th, 11th, and 15th), the trench fighter picks up another type of firearm, gaining these bonuses for those types as well. Furthermore, when behind partial, normal, or improved cover, a trench fighter gains an additional +2 AC bonus from the cover. This ability replaces armor training 1, 2, 3, and 4."},{"type":"Symbiote","kind":"Ex","details":"A unique relationship with trench mists grants trench zombies immunity to acid. In addition, when a trench zombie reaches 0 hit points and is destroyed, the mustard-colored mist that animates the creature bursts violently from its damaged form. All creatures adjacent to the trench zombie are exposed to the toxic gas and take 4d6 points of acid damage. If the trench zombie is enveloped within the fog of its parent trench mist when this death burst occurs, the mist's fast healing ability increases by 1 for a number of rounds equal to the Hit Dice of the destroyed trench zombie. The effects of the deaths of multiple symbiotic trench zombies stack."}],"description":"A trench zombie is a rotting creature leaking sulfurous fumes from beneath its acid-burned, peeling skin, and bristling with the armaments it possessed in its horrifying death. Retaining many of the memories and skills it possessed in life, a trench zombie contributes its intelligence into a sort of hive mind for the trench mist that originally spawned it, creating a true symbiosis between the two-a gift the trench zombie repays upon its destruction, when the horrific fumes that granted it unlife go back to the trench mist that birthed it. Trench zombies are foul and vengeful, and are canny enough to lurk within the nurturing embrace of their mother mist, which provides them concealment without impairing their senses. Those seeking trench zombies' destruction typically must enter the engulfing body of a trench mist if they are to ward off the zombies' ranged attacks. Trench zombies are created using the juju zombie template, but they lose the juju zombie's immunity to magic missile, which is replaced by immunity to acid. Trench zombies also gain the following special ability Symbiote (Ex).","ecology":"","habitat_society":"","gear":"M1914 concussion grenades (2), Mosin-Nagant M1891 rifle with 20 metal cartridges, socket bayonet, gas mask"},{"name":"Tribal Totem","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +7 natural","hp":69,"hd":"9d10+20","hdvalue":9,"fort":3,"ref":5,"will":1,"dr":"5/slashing","immunities":["construct traits"],"weaknesses":["ceremonial activation","vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"2 slams +12 (1d10+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spirit link"}],"strength":17,"dexterity":14,"wisdom":13,"charisma":14,"baseatk":9,"cmb":3,"cmd":13,"cmd_special":"can't be tripped or bull rushed","sq":[{"type":"effigy"},{"type":"mouthpiece"}],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"Value none","description_visual":"With the splintering sound of dry, cracking wood, a human-sized graven image lurches to life. Its features shift and reform with every step, cycling through a variety of faces both strange and oddly familiar. Bits of feather, leaves, and decorative stone embellish its surface, and the strong smell of lacquer and resin assaults the senses as it draws near with a menacing, ponderous gait.","source":"AP 39","special_abilities":[{"type":"Ceremonial Activation","kind":"Su","details":"A tribal totem stands inert unless empowered each day by spiritual energy. This activation requires that at least 10 participants perform an hour-long ceremony of chanting and adoration. For each hour this ritual lasts, the totem remains alert and functional for 1 day. The worshipers need not include the creator or possess any special divine powers."},{"type":"Effigy","kind":"Su","details":"As a full-round action once per day, a tribal totem can mimic the shape of any Small or Medium humanoid within its line of sight, reforming itself into a wooden depiction of that creature. Upon doing so, the target can be affected by the effigy ability. While in this shape, the tribal totem knows the location of its target as if persistently using the spell locate creature. A warp wood or wood shape spell immediately forces the tribal totem to revert to its normal form. Although the tribal totem may only use this ability once per day, it can retain a shape indefinitely."},{"type":"Mouthpiece","kind":"Sp","details":"Although a tribal totem cannot speak on its own, every day it can store a single message for its creator and repeat that message upon a prescribed condition. This ability functions as the magic mouth spell, and its creator may change or reset the conditions of the message each day."},{"type":"Spirit Link","kind":"Su","details":"As a standard action, a tribal totem may attempt to join its animating energies with a creature within its line of sight that also shares its likeness (as per the effigy ability). The target can resist this effect with a DC 16 Will save. If this save fails, the target is affected as if it had cast the spell shield other, taking half the damage inflicted upon the tribal totem. In addition, any spell with a range of \"creature touched\" cast upon the tribal totem affects the linked creature rather than the construct. If the spell allows a saving throw, the linked creature can make a saving throw as normal to resist the effect. Spirit link lasts for 4 hours and ends immediately if the tribal totem no longer possesses the target's shape. The save DC is Charisma-based."}],"description":"Tribal totems represent a significant cultural achievement for their adopted tribe. Imbued with a spark of life from the continued worship of those they protect, they stand as lifelong guardians of their villages, defending them against enemies and predators alike. To aid them in this function, they also possess the unusual ability to reshape themselves into the likeness of other creatures, targeting them with eerie pains and ailments. This ability enables their tribe to more actively hunt down such enemies while their quarry is hindered and tracked by the totem.\n\nAs mindless automatons, tribal totems remain ever dependent on their creators to direct them. Some serve only a defensive role, strategically placed within villages to aid against attacks. Others carry stored messages on their tribe's behalf or vocalize their creator's words. Rarer still are the tribal totems purposed for war, which emerge from the jungle as a potent force capable of spearheading invasions and targeting enemy champions.\n\nWhile most tribal totems are made of wood and combine exaggerated features of folkloric monsters with simple decorations and images of strength (like streaks of blood, the claws of defeated beasts, or enemy skulls), few look exactly alike, as each embodies the deities, fears, or legends of its creator's people. Tribal totems tend to stand 7 ft. tall and weigh over 300 pounds.\n\nEcology As constructs, tribal totems have no significant ecological niche. They exist at the whim of their creators and protect their assigned tribes from harm. The divine spark that powers them emanates from the continued adulation and combined spiritual energy of the tribe, but relies upon constant rekindling. Each morning, the totem requires lengthy ritual adoration to renew its power. Otherwise, the totem remains still, appearing to be nothing more than a decorative statue.\n\nDuring elaborate festivals and revels, tribal natives usually spend several hours honoring the totem to ensure it remains vigilant for many days. They also take care to mend and repair any damage it might have suffered on their behalf. Once charged in this manner, the totem may operate remotely for many days at a time, undertaking longer trips on the tribe's behalf to hunt down enemies whose likeness it acquires.\n\nHabitat & Society Tribal shamans, oracles, or witchdoctors most commonly undertake the rituals necessary to construct a tribal totem, guiding the rest of the tribe in worshiping and maintaining it. The totem only obeys the commands of its creator or someone appointed by her. In the event of conf licting orders, it always obeys its creator above anyone else loaned such authority. Typically, a tribal totem spends its entire existence within the confines of its creator's village, and is completely dependent on the continuing worship of the tribe to give it a semblance of life. Only in rare cases might a multitude of tribes gather their totems together for some shared offensive. Tales also tell of crazed hermits and shamanic outcasts who have created multiple tribal totems and then set them against specific individuals or whole tribes who garner their ire.\n\nGreater Tribal Totems Legends also tell of more advanced versions of tribal totems, some reaching Large or even Huge size. Serving as guardians of important religious or cultural sites, these totems possess multiple faces, one on each side of their heads, enabling them to take on the conjoined likeness of up to four victims at a time. They also gain the following additional abilities: • +3 natural armor • +4 Strength, +2 Wisdom, +2 Charisma • All-Around Vision (Ex) A greater tribal totem gains a +6 bonus on Perception checks and cannot be flanked.\n\n• Extended Effigy (Su) A greater tribal totem is no longer dependent on line of sight to affect victims with its shared condition ability. Instead, it can extend this power to any creature that has ever been in its line of sight and is currently within 5 miles, often enabling its creators to inf lict terrible punishments upon their enemies through the totem's connection.\n\nConstruction A tribal totem is always carved from a single type of wood chosen for its density and beauty-typically, ebony, mahogany, or some other valuable resource whose value is at least 1,000 gp. Some tribes use ivory instead, lashing together the pieces and then relying on the magic of the totem's construction to knit everything into a single whole. Decorations of leafy fronds, stones, animalistic trophies, and paint help complete the appearance.\n\nInitially, a creator shapes a totem's features into a ferocious, monstrous image. Then, the application of the proper spells enables the construct to alter its appearance to mimic other creatures.\n\nTribal Totem CL 8th; Price 19,000 gp Construction Requirements Craft Construct, animate objects, disguise self, locate creature, magic mouth, shield other, creator must be caster level 11th; Skill Craft (carpentry) and Craft (sculpture) DC 20; Cost 10,000 gp.\n\nGreater Tribal Totem CL 9th; Price 22,000 gp Construction Requirements Craft Construct, animate objects, arcane eye, disguise self, locate creature, magic mouth, shield other, creator must be caster level 13th; Skill Craft (carpentry) and Craft (sculpture) DC 24; Cost 12,000 gp.","ecology":"As constructs, tribal totems have no significant ecological niche. They exist at the whim of their creators and protect their assigned tribes from harm. The divine spark that powers them emanates from the continued adulation and combined spiritual energy of the tribe, but relies upon constant rekindling. Each morning, the totem requires lengthy ritual adoration to renew its power. Otherwise, the totem remains still, appearing to be nothing more than a decorative statue.\n\nDuring elaborate festivals and revels, tribal natives usually spend several hours honoring the totem to ensure it remains vigilant for many days. They also take care to mend and repair any damage it might have suffered on their behalf. Once charged in this manner, the totem may operate remotely for many days at a time, undertaking longer trips on the tribe's behalf to hunt down enemies whose likeness it acquires.","habitat_society":"Tribal shamans, oracles, or witchdoctors most commonly undertake the rituals necessary to construct a tribal totem, guiding the rest of the tribe in worshiping and maintaining it. The totem only obeys the commands of its creator or someone appointed by her. In the event of conf licting orders, it always obeys its creator above anyone else loaned such authority. Typically, a tribal totem spends its entire existence within the confines of its creator's village, and is completely dependent on the continuing worship of the tribe to give it a semblance of life. Only in rare cases might a multitude of tribes gather their totems together for some shared offensive. Tales also tell of crazed hermits and shamanic outcasts who have created multiple tribal totems and then set them against specific individuals or whole tribes who garner their ire.\n\nGreater Tribal Totems Legends also tell of more advanced versions of tribal totems, some reaching Large or even Huge size. Serving as guardians of important religious or cultural sites, these totems possess multiple faces, one on each side of their heads, enabling them to take on the conjoined likeness of up to four victims at a time. They also gain the following additional abilities: • +3 natural armor • +4 Strength, +2 Wisdom, +2 Charisma • All-Around Vision (Ex) A greater tribal totem gains a +6 bonus on Perception checks and cannot be flanked.\n\n• Extended Effigy (Su) A greater tribal totem is no longer dependent on line of sight to affect victims with its shared condition ability. Instead, it can extend this power to any creature that has ever been in its line of sight and is currently within 5 miles, often enabling its creators to inf lict terrible punishments upon their enemies through the totem's connection.\n\nConstruction A tribal totem is always carved from a single type of wood chosen for its density and beauty-typically, ebony, mahogany, or some other valuable resource whose value is at least 1,000 gp. Some tribes use ivory instead, lashing together the pieces and then relying on the magic of the totem's construction to knit everything into a single whole. Decorations of leafy fronds, stones, animalistic trophies, and paint help complete the appearance.\n\nInitially, a creator shapes a totem's features into a ferocious, monstrous image. Then, the application of the proper spells enables the construct to alter its appearance to mimic other creatures.\n\nTribal Totem CL 8th; Price 19,000 gp Construction Requirements Craft Construct, animate objects, disguise self, locate creature, magic mouth, shield other, creator must be caster level 11th; Skill Craft (carpentry) and Craft (sculpture) DC 20; Cost 10,000 gp.\n\nGreater Tribal Totem CL 9th; Price 22,000 gp Construction Requirements Craft Construct, animate objects, arcane eye, disguise self, locate creature, magic mouth, shield other, creator must be caster level 13th; Skill Craft (carpentry) and Craft (sculpture) DC 24; Cost 12,000 gp."},{"name":"Ubashki Lynx","cr":6,"xp":2400,"alignment":"NE","size":"Large","type":"undead","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 Dex, +5 natural, -1 size","hp":60,"hd":"8d8+24","hdvalue":8,"fort":4,"ref":7,"will":7,"immunities":["undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"bite +11 (2d6+5 plus ubashki rot), 2 claws +10 (1d8+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"piercing howl"},{"type":"rake","details":"2 claws +10, 1d8+5"}],"strength":21,"dexterity":17,"intelligence":2,"wisdom":12,"charisma":15,"baseatk":6,"cmb":12,"cmd":25,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Climb","value":10},{"skill":"Perception","value":6},{"skill":"Stealth","value":8}],"environments":["temperate deserts","warm deserts"],"organizations":["solitary","pair"],"treasure":"none","source":"Lost Kingdoms","special_abilities":[{"type":"Piercing Howl","kind":"Su","details":"When an ubashki lynx howls, all creatures except other undead within a 300-foot spread must succeed at a DC 16 Will save or become frightened for 1d4 rounds. This is a sonic, mind-affecting effect. Whether or not the save is successful, an affected creature is immune to the same ubashki lynx's piercing howl for 24 hours. The save DC is Charisma-based."},{"type":"Ubashki Rot","kind":"Su","details":"Curse and disease-bite; save Fort DC 16; onset 1 hour; frequency 1/day; effect 1d6 Str and 1d6 Wis; cure -. Ubashki rot is both a curse and a disease and can only be cured if the curse is first removed, at which point the disease can be magically removed. Even after the curse element of ubashki rot is lifted, a creature suffering from it cannot recover naturally over time. Anyone casting a conjuration (healing) spell on the afflicted creature must succeed at a DC 20 caster level check, or the spell is wasted and the healing has no effect. The save DC is Charisma-based."}],"description":"Perhaps no beasts were trusted into the afterlife so much as felines, however, who were almost without exception buried alongside deceased pharaohs or at the very least inscribed into their burial chamber walls. Those cats that rose from the dead- either because of the foul magical energies of a pharaoh's crypt or thanks to the necromantic magic of a restless undead pharaoh herself-were known as ubashki.\n\nUbashki were prized for being stealthy, agile, and preternaturally perceptive sentries that made for effective spies and watch guards for the tombs of Osirian god-kings. Emperors often filled their crypts with the bodies of strangled and mutilated cats before they themselves were entombed, believing that a feline's suffering in life would translate to strength in undeath.\n\nWhether or not such theories were true is up for debate, but those felid creatures that did rise from death with their masters were indeed beasts to be reckoned with, and a sizeable pack of the mummified things could very well spell the end for would-be tomb raiders. Ranging from tiny housecats to desert-roaming mountain lions, the feline enshrined with a deceased pharaoh varied in type depending on the predilections of its master, but all were known to be signif icantly more powerful than their living iterations.","ecology":"","habitat_society":""},{"name":"Verdurous Ooze","cr":6,"xp":2400,"race":"ooze","alignment":"N","size":"Medium","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"auras":["enliven (15 ft., DC 20)","sleep aura (30 ft., DC 20)"],"ac":5,"ac_touch":5,"ac_flat_footed":5,"ac_mods":"-5 Dex","hp":85,"hd":"9d8+54","hdvalue":9,"fort":9,"ref":-2,"will":-2,"defensive_abilities":["split"],"immunities":["acid","fire","mind-affecting effects","ooze traits","slashing and piercing damage"],"speed":[{"type":"land","speed":20}],"melee":"slam +9 (1d6+4 plus 1d6 acid and grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid"},{"type":"constrict","details":"1d6+4 plus 1d6 acid"},{"type":"enliven"}],"strength":16,"dexterity":1,"constitution":22,"wisdom":1,"charisma":1,"baseatk":6,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":14,"cmd_special":"can't be tripped","skills":[{"skill":"Stealth","value":-4,"special":"+16 in forest and plains areas"}],"environments":["temperate forests","temperate plains"],"organizations":["solitary"],"treasure":"none","description_visual":"A pool of greenish muck, blossoming with weird vegetable-like growths and sap-seeping boils, twitches into unnatural motion as a pseudopod springs outward, dragging the entire grotesque mass forward with an ameboid life.","source":"AP 35","special_abilities":[{"type":"Acid","kind":"Ex","details":"A verdurous ooze secretes a digestive acid that dissolves flesh and metal quickly. Each time a creature takes damage from a verdurous ooze's acid, the creature's metal equipment and armor take the same amount of damage from the acid. A DC 21 Reflex save prevents damage to such items. A metal or natural weapon that strikes a verdurous ooze takes 1d6 points of acid damage unless the weapon's wielder succeeds on a DC 21 Reflex save. If a verdurous ooze remains in contact with a metal object for 1 full round, it inflicts 20 points of acid damage (no save) on the object. The save DCs are Constitution-based."},{"type":"Enliven","kind":"Sp","details":"The chemicals emitted by a verdurous ooze cause nearby plants to twitch into life. While in areas covered in natural growth, all squares within 15 ft. of the verdurous ooze are affected as if by the spell entangle. The verdurous ooze has no control over this effect, and if dispelled the effect renews after 1d4 rounds. The save DC is Constitution-based."},{"type":"Sleep Aura","kind":"Su","details":"The chemicals emitted by a verdurous ooze have a stronger and opposite effect on living, non-plant creatures that come within a 30-foot radius. All living creatures within the area must make a DC 21 Will save or fall asleep for a number of rounds equal to the ooze's HD. Creatures immune to poison are also immune to this effect. Whether or not the save is successful, that creature cannot be affected again by the same verdurous ooze's sleep aura for 24 hours. This is a nonmagical sleep effect. The save DC is Constitution-based."},{"type":"Split","kind":"Ex","details":"Slashing and piercing weapons deal no damage to a verdurous ooze. Instead, if the verdurous ooze would have taken 10 or more points of damage from a single slashing or piercing attack, it splits into two identical oozes, each with half of the original's current hit points (round down). Slashing or piercing attacks that deal less than 10 points of damage don't cause a verdurous ooze to split. Damage from multiple slashing or piercing attacks isn't cumulative. A verdurous ooze with 15 hit points or less cannot be further split and dies if reduced to 0 hit points."}],"description":"Verdurous oozes are animate masses of protoplasm of a sickly green hue. At rest, their flat bodies stand roughly 5 inches tall and can stretch out to a wide diameter, their surfaces blossoming into what look like thick tangles of mossy roots and gnarled vegetation as they lie still. Known to emit invisible but dangerous chemicals, these masses of slinking muck cause nearby plants to writhe and coil as if alive, while shocking animals into a temporary but deathly torpor. As such, they rarely must hunt to find food, instead sensing passing creatures and preying upon them after they succumb to the oozes' sleep aura. Always ravenous, the powerful acids that comprise these oozes quickly dissolve the flesh of their meals. A verdurous ooze typically weighs 300 pounds and can easily spread to fill a 5-foot-square area. While moving, such crawling muck rises only a few inches tall, though its structure might grow and boil up to a height of 2 or 3 ft. if let undisturbed for a matter of days. Spontaneously grown structures collapse and melt back into the ooze's body as soon as it begins moving again. Ecology Verdurous oozes settle in locations with abundant food, rarely moving far except to feed upon comatose prey that has come too close or to reproduce. Verdurous oozes primarily gain sustenance from the small birds, mammals, and insects that fall prey to their sleep aura, but also prove well suited to devouring larger creatures that fall asleep nearby. Every 2 or 3 years, verdurous oozes collect deep in forests and swamps, clustering in secluded locales tainted by reeking natural compost or the escape of natural gases from the land. As many as 10 oozes might gather during one of these grotesque moots. To reproduce, four verdurous oozes merge to become a greater verdurous ooze. Greater oozes are far more active and hungry than their lesser kin, constantly wandering, feeding, and growing. After several months, the greater verdurous ooze splits into 10 to 15 new verdurous oozes. These new verdurous oozes grow to full size within 6 months. Habitat & Society Verdurous oozes primarily live in temperate forests and plains among high grasses or cultivated crops, though they might also be found in warm plains and jungle environments. As mindless creatures, they pay little attention to others of their kind, save when drawn to reproduce. A notable fact about verdurous oozes is that they beneficially impact nearby plant life; their secretions act as a kind of natural fertilizer. Trees, grass, flowers-all flora benefits from the existence of a nearby verdurous ooze. Over time, this can lead to an increase in the fauna in the area, as they seek to enjoy the rich, lush plants that make up their diet and in turn become prey for the stealthy ooze. Thus, another sign that a verdurous ooze is, or has been, in a particular area is the skeletons of animals that it has consumed, which are left behind once the flesh has been absorbed. Resourceful evil humanoids sometimes take advantage of verdurous oozes' relative lassitude and difficultly escaping from simple pits or other containers, trapping them near the entrances to their lairs. In such instances, the oozes' chemical secretions provide an extra defense for those aware of their presence and the dangers of coming too close. Greater Verdurous Ooze Greater verdurous oozes are formed when several green oozes merge together as part of their reproductive process. They are similar in form but much larger, and while still green, exhibit white and red lines that resemble veins running through them. They are even more voracious and dangerous than standard green oozes, as they eat and eat to gain enough mass to reproduce. A greater verdurous ooze typically weighs 2,400 pounds and can easily spread to fill a 10-foot-square area.","ecology":"Verdurous oozes settle in locations with abundant food, rarely moving far except to feed upon comatose prey that has come too close or to reproduce. Verdurous oozes primarily gain sustenance from the small birds, mammals, and insects that fall prey to their sleep aura, but also prove well suited to devouring larger creatures that fall asleep nearby. Every 2 or 3 years, verdurous oozes collect deep in forests and swamps, clustering in secluded locales tainted by reeking natural compost or the escape of natural gases from the land. As many as 10 oozes might gather during one of these grotesque moots. To reproduce, four verdurous oozes merge to become a greater verdurous ooze. Greater oozes are far more active and hungry than their lesser kin, constantly wandering, feeding, and growing. After several months, the greater verdurous ooze splits into 10 to 15 new verdurous oozes. These new verdurous oozes grow to full size within 6 months.","habitat_society":"Verdurous oozes primarily live in temperate forests and plains among high grasses or cultivated crops, though they might also be found in warm plains and jungle environments. As mindless creatures, they pay little attention to others of their kind, save when drawn to reproduce. A notable fact about verdurous oozes is that they beneficially impact nearby plant life; their secretions act as a kind of natural fertilizer. Trees, grass, flowers-all flora benefits from the existence of a nearby verdurous ooze. Over time, this can lead to an increase in the fauna in the area, as they seek to enjoy the rich, lush plants that make up their diet and in turn become prey for the stealthy ooze. Thus, another sign that a verdurous ooze is, or has been, in a particular area is the skeletons of animals that it has consumed, which are left behind once the flesh has been absorbed. Resourceful evil humanoids sometimes take advantage of verdurous oozes' relative lassitude and difficultly escaping from simple pits or other containers, trapping them near the entrances to their lairs. In such instances, the oozes' chemical secretions provide an extra defense for those aware of their presence and the dangers of coming too close. Greater Verdurous Ooze Greater verdurous oozes are formed when several green oozes merge together as part of their reproductive process. They are similar in form but much larger, and while still green, exhibit white and red lines that resemble veins running through them. They are even more voracious and dangerous than standard green oozes, as they eat and eat to gain enough mass to reproduce. A greater verdurous ooze typically weighs 2,400 pounds and can easily spread to fill a 10-foot-square area."},{"name":"Very Young Copper Dragon","cr":6,"xp":2400,"alignment":"CG","size":"Small","type":"dragon","subtypes":["earth"],"init":6,"senses":[{"type":"dragon senses"}],"ac":20,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+2 Dex, +7 natural, +1 size","hp":59,"hd":"7d12+14","hdvalue":7,"fort":7,"ref":7,"will":7,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"average"}],"speed_mod":"climb stone","melee":"bite +10 (1d6+3/19-20), 2 claws +10 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"40-ft. line, DC 15, 4d6 acid"},{"type":"slow breath"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"grease"}]}],"strength":15,"dexterity":14,"constitution":15,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":7,"cmb":8,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Expertise"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Craft (traps)","value":12},{"skill":"Fly","value":14},{"skill":"Perception","value":12},{"skill":"Perform (comedy)","value":9},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":16},{"skill":"Use Magic Device","value":12}],"languages":["Common","Draconic","Gnome"],"environments":["warm hills"],"organizations":["solitary"],"treasure":"triple","description_visual":"Bright, shining copper scales run from the horn-crowned head to the ridged tail of this long-winged dragon.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Climb Stone","kind":"Ex","details":"A copper dragon can climb on stone surfaces as though using the spider climb spell."},{"type":"Slow Breath","kind":"Su","details":"Instead of a line of acid, a copper dragon can breathe a cone of slowing gas. Those in the cone must make a Fortitude save or be slowed (as per the spell slow) for 1d6 rounds plus 1 round per age category of the dragon."}],"description":"This whimsical dragon spends most of its time in combat trying to annoy and frustrate its enemies.","ecology":"","habitat_society":""},{"name":"Very Young Green Dragon","cr":6,"xp":2400,"alignment":"LE","size":"Medium","type":"dragon","subtypes":["air"],"init":1,"senses":[{"type":"dragon senses"}],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":59,"hd":"7d12+14","hdvalue":7,"fort":7,"ref":6,"will":8,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"bite +10 (1d8+4), 2 claws +10 (1d6+3), 2 wings +5 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"30-ft. cone, DC 15, 4d6 acid"}],"strength":17,"dexterity":12,"constitution":15,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":7,"cmb":10,"cmd":21,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":11},{"skill":"Knowledge (nature)","value":11},{"skill":"Perception","value":13},{"skill":"Spellcraft","value":11},{"skill":"Stealth","value":11},{"skill":"Survival","value":11},{"skill":"Swim","value":21}],"languages":["Common","Draconic"],"sq":[{"type":"water breathing"},{"type":"woodland stride"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"triple","description_visual":"Scales the color of emeralds armor this ferocious dragon. A single sharp horn protrudes from the end of its toothy snout.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Water Breathing","kind":"Ex","details":"A green dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."},{"type":"Woodland Stride","kind":"Ex","details":"A very young or older green dragon can move through any sort of foliage at full speed without taking damage or suffering impairment. Areas of foliage that have been magically manipulated affect it normally."}],"description":"Green dragons dwell in the ancient forests of the world, prowling under towering canopies in search of prey. Of all the chromatic dragons, green dragons are perhaps the easiest to deal with diplomatically.","ecology":"","habitat_society":""},{"name":"Vetala","cr":6,"xp":2400,"race":"human vetala","classes":[{"class":"oracle","level":5}],"alignment":"NE","size":"Medium","type":"undead","subtypes":["augmented humanoid","human"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+4 armor, +2 Dex, +1 dodge, +4 natural","hp":61,"hd":"5d8+35","hdvalue":5,"hp_mods":["fast healing 5"],"fort":8,"ref":4,"will":6,"defensive_abilities":["channel resistance +4"],"dr":"10/magic and good","immunities":["undead traits"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"weaknesses":["vetala weaknesses"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"2 claws +7 (1d6+4 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drain prana","details":"DC 18"},{"type":"malevolence"},{"type":"paralysis","details":"1d4+1 rounds, DC 18"},{"type":"possess corpse"}],"spellsknown_caster":"oracle","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":6,"spells":[{"spell":"death knell"},{"spell":"false life"},{"spell":"inflict moderate wounds"},{"spell":"levitate"},{"spell":"minor image"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"command"},{"spell":"doom"},{"spell":"inflict light wounds"},{"spell":"obscuring mist"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"guidance"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":18,"dexterity":15,"intelligence":16,"wisdom":12,"charisma":22,"baseatk":3,"cmb":7,"cmd":20,"feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Blind-Fight","type":"bonus"},{"feat":"Combat Casting"},{"feat":"Deceitful","type":"bonus"},{"feat":"Dodge"},{"feat":"Extra Revelation"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Skill Focus (Disguise)","type":"bonus"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Climb","value":10},{"skill":"Diplomacy","value":14},{"skill":"Disguise","value":27},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":11},{"skill":"Stealth","value":16}],"languages":["Common","Infernal","Vudrani"],"sq":[{"type":"oracle's curse","details":"haunted"},{"type":"revelations","details":"death's touch, undead servitude, voice of the grave"}],"environments":["any (Vudra)"],"organizations":["solitary"],"treasure":"none","description_visual":"With its bloodless flesh and eyes the color of deepest night, this imperious being obviously no longer numbers among the living.","group":"Vampire","source":"Inner Sea Bestiary","description":"While most of the Inner Sea's vampires lust for living blood, the mysterious vetalas hunger for a more intangible force: the energy that infuses mortal minds. Referred to as consciousness or psyche by some, the academics of Vudra- from where most vetalas hail-call this fundamental vital force prana. Regardless of their desire's name, vetalas prey upon those who show creative promise, possess potent force of will, or seem destined for greatness, draining the most brilliant sources of mortal light to fuel their own unnatural embers. Their dark mastery of life force allows vetalas to possess corpses or even overwhelm the minds of living creatures. With these stolen masks and the resources of abducted lives, they work their foul wills.\n\nVetalas are said to be the spirits of children \"born evil,\" who never received burial rites upon their deaths. Sometimes one of these evil spirits takes hold of a corpse- not necessarily its own-which becomes its anchor to the mortal world. Such young souls seek out experiences and life energy, becoming as wicked as any other vampire as they endlessly indulge their profane, deathless desires.","ecology":"","habitat_society":"","gear":"chain shirt, cloak of resistance +1, potions of invisibility [2]"},{"name":"Vulpinal","cr":6,"xp":2400,"alignment":"NG","size":"Small","type":"outsider","subtypes":["agathion","extraplanar","good"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"low-light vision"}],"auras":["calm emotions (30 ft.)"],"ac":22,"ac_touch":14,"ac_flat_footed":19,"ac_mods":"+4 armor, +3 Dex, +4 natural, +1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":5,"ref":10,"will":7,"save_mods":"+4 vs. poison","dr":"10/evil or silver","immunities":["electricity","petrification"],"resists":[{"type":"cold","value":10},{"type":"sonic","value":10}],"sr":17,"speed":[{"type":"land","speed":30}],"melee":"bite +11 (1d4+1), 2 claws +11 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"mage armor"},{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"major image"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"dimension door","details":"self plus 50 lbs. of objects only"},{"spell":"dispel evil"},{"spell":"flame arrow"},{"spell":"holy smite"},{"spell":"remove disease"}]}],"strength":12,"dexterity":16,"constitution":17,"intelligence":19,"wisdom":15,"charisma":16,"baseatk":7,"cmb":7,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+18 jump"},{"skill":"Bluff","value":13},{"skill":"Knowledge (any one)","value":21},{"skill":"Knowledge (arcana)","value":21},{"skill":"Knowledge (planes)","value":21},{"skill":"Perception","value":12},{"skill":"Perform (any one)","value":13},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":17},{"skill":"Use Magic Device","value":10}],"languages":["Celestial","Common","Draconic","Infernal","speak with animals","truespeech"],"sq":[{"type":"bardic knowledge","details":"+7"},{"type":"lay on hands","details":"3d6, 6/day, as a 7th-level paladin"}],"environments":["any land (Nirvana)"],"organizations":["solitary","pair","team (3-12)"],"treasure":"standard (masterwork musical instrument)","description_visual":"This bright-eyed, anthropomorphic fox is dressed in simple traveling clothes and carries a musical instrument in one hand.","group":"Agathion","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Calm Emotions Aura","kind":"Su","details":"A vulpinal's aura acts like a calm emotions spell with a radius of 30 ft. Any creature entering this area must make a Will save (DC 16) to resist the effect. A creature that makes its save is immune to that vulpinal's aura for 24 hours. The save DC is Charisma-based."}],"description":"Among the smallest of the agathions, vulpinals tend to be the most outspoken and friendly of their kind, and also the most far-ranging across the planes. A vulpinal looks like a humanoid fox, often with brilliantly colored fur (usually red or red-brown, though silver isn't uncommon) and a tail as long as its height. As the bards and sages of the agathions, they dress in functional clothing, typically embellishing a single article to show their creativity and personality. Most appear to be adults, though others look more like fox kits (with shorter stature and larger eyes) while some look much older (leaner, with gray fur on the muzzle, chest, and tail). Their hands are humanoid in shape, with tiny clawed fingers.\n\nA typical vulpinal prefers a life of solitary travel, though they have been known to pair up or travel in groups if they find like-minded individuals who have much to teach and share. They are particularly fond of lillends, and these winged azatas can easily carry the child-sized vulpinals, giving vulpinals many opportunities to share stories. Indeed, for a vulpinal, there are few greater pleasures than sharing their knowledge-acting as sages of the planes, teaching songs and dances from exotic places, and composing poems about beautiful places in the natural world. Though they are gentle by nature, they fight to defend beauty, especially if their magic can bolster the more martial celestial races.\n\nA vulpinal stands about 3 ft. in height and weighs 50 pounds.","ecology":"","habitat_society":""},{"name":"Will-o'-Wisp","cr":6,"xp":2400,"alignment":"CE","size":"Small","type":"aberration","subtypes":["air"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":26,"ac_touch":26,"ac_flat_footed":16,"ac_mods":"+5 deflection, +9 Dex, +1 dodge, +1 size","hp":40,"hd":"9d8","hdvalue":9,"fort":3,"ref":12,"will":11,"defensive_abilities":["natural invisibility"],"immunities":["magic"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"shock +16 touch (2d8 electricity)","space":"5 ft.","reach":"5 ft.","strength":1,"dexterity":29,"constitution":10,"intelligence":15,"wisdom":16,"charisma":14,"baseatk":6,"cmb":26,"cmb_special":"+2 vs. trip, +4 vs. grapple","cmd":35,"cmd_special":"+2 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":21},{"skill":"Bluff","value":11},{"skill":"Escape Artist","value":21},{"skill":"Fly","value":31},{"skill":"Perception","value":17},{"skill":"Stealth","value":25}],"languages":["Aklo","Common"],"sq":[{"type":"feed on fear"}],"environments":["any swamps"],"organizations":["solitary","pair","string (3-4)"],"treasure":"incidental","description_visual":"This faintly glowing ball of light bobs gently in the air, the nebulous image of what might be a skull visible somewhere in its depths.","source":"PFRPG Bestiary","special_abilities":[{"type":"Feed on Fear","kind":"Su","details":"Any time a will-o'-wisp is within 15 ft. of a dying creature or creature subject to a fear effect, it gains fast healing 5."},{"type":"Immunity to Magic","kind":"Ex","details":"Will-o'-wisps are immune to all spells and spell-like abilities that allow spell resistance, except magic missile and maze."},{"type":"Natural Invisibility","kind":"Ex","details":"Will-o'-wisps have the ability to extinguish their natural glow as a move action, effectively becoming invisible, as per the spell."}],"description":"Every trapper and bog farmer living near marshes or swamps has his own name for these faintly glowing balls of light-jack o' the lanterns, corpse candles, walking fires, pine lights, spooklights, rushlights-but all recognize them as dangerous predators and false guides in the darkness. Evil creatures that feed on the strong psychic emanations of terrified creatures, will-o'-wisps delight in tempting gullible travelers into dangerous situations. In the wild lands where they're most common, will-o'-wisps favor simple tactics like positioning themselves over cliffs or quicksand where they can easily be mistaken for lanterns (especially if they can set their traps near actual signal lanterns), allowing them to lure unwary travelers into perilous situations. On rare occasions, will-o'- wisps seeking easier pickings will move into a city and take up residence near gallows or follow along invisibly behind an army in order to harvest the fear of the dying men; why the vast majority choose to remain in the swamps where victims are scarce remains a mystery. Will-o'- wisps only use their electric shock ability under extreme duress, preferring to let other creatures or hazards claim their victims while they float nearby and feast. Will-o'-wisps can glow any color they choose, but are most frequently yellow, white, green, or blue. They can even vary their luminosity to create patterns-many will-o'- wisps are fond of creating vague skull-like shapes in their glow to further terrify their victims. Their actual bodies are barely visible globes of translucent spongy material 1 foot across and weighing 3 pounds, capable of emitting light from every surface. A will-o'-wisp's light is approximately as bright as a torch, and though they don't seem to use sound to communicate with each other, they hear perfectly and can vibrate their bodies rapidly to simulate speech. While vilif ied by most other sentient creatures, will-o'-wisps are actually quite intelligent, if utterly alien in their reasoning. Sometimes organized into groups called \"strings,\" their society and goals remain complete unknowns to outsiders, as do their origins, though they have sometimes been known to strike bargains with those who can offer them vast quantities of appropriately frightened victims. As will-o'-wisps don't age, and are effectively immortal unless killed by violence, particularly ancient will-o'-wisps can serve as fantastic repositories of knowledge from the ancient past, although convincing one of these cruel creatures to cooperate with an interrogation can be a trick in and of itself.","ecology":"","habitat_society":""},{"name":"Witchwyrd","cr":6,"xp":2400,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+4 armor, +2 Dex, +3 natural","hp":68,"hd":"8d10+24","hdvalue":8,"fort":7,"ref":8,"will":9,"defensive_abilities":["absorb force"],"dr":"5/magic","speed":[{"type":"land","speed":30}],"melee":"ranseur +11 (2d4+4/x3), 2 slams  +6 (1d4+1 plus grab) or  4 slams +11 (1d4+3 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with ranseur)","special_attacks":[{"type":"force bolt"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"floating disk"},{"spell":"mage armor"},{"spell":"resist energy","details":"one at a time"},{"spell":"unseen servant"}]},{"frequency":"1/day","spells":[{"spell":"dimension door"},{"spell":"resilient sphere"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"suggestion"}]}],"strength":16,"dexterity":15,"constitution":17,"intelligence":18,"wisdom":13,"charisma":20,"baseatk":8,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":23,"feats":[{"feat":"Deflect Arrows","type":"bonus"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Persuasive"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":11},{"skill":"Intimidate","value":18},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (geography)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":5},{"skill":"Use Magic Device","value":9}],"languages":["Common","Draconic","one or more planar languages","tongues"],"environments":["any land"],"organizations":["solitary","entourage (1 witchwyrd and 2-5 humanoid guards)","enclave (2-5 witchwyrds and 11-20 humanoid guards)"],"treasure":"double","description_visual":"This gray-skinned humanoid wears fine red robes. The being has four arms, each ending in a three-fingered hand.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Absorb Force","kind":"Su","details":"Once per round, a witchwyrd can use a free hand to \"catch\" a magic missile fired at it. This absorbs the missile and manifests as a glowing nimbus around that hand (which is no longer considered free). The energy lasts 6 rounds or until it is used to create a force bolt. To use this ability, the witchwyrd must be aware of the incoming magic missile and cannot be flat-footed."},{"type":"Force Bolt","kind":"Su","details":"A witchwyrd can \"throw\" a magic missile (1d4+1 damage) from each free hand as a free action (maximum of two per round). If it has absorbed a magic missile, it can throw an additional force bolt that round, expending the absorbed energy (maximum of two additional bolts per round)."}],"description":"Alien merchants that travel between planets and planes, witchwyrds stand 7 ft. tall, weigh 300 pounds, and are covered in hairless blue-gray skin. Witchwyrds new to a market or eager to avoid identification during an important business deal fold their second sets of flexible arms behind their backs and dress in robes, the better to pass as a lessinfamous humanoid race. Witchwyrds tend to prefer the driest, warmest regions of the areas they visit-perhaps an indicator of their mysterious home world.","ecology":"","habitat_society":""},{"name":"Wood Giant","cr":6,"xp":2400,"alignment":"CG","size":"Large","type":"humanoid","subtypes":["giant"],"init":5,"senses":[{"type":"low-light vision"}],"ac":20,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+2 armor, +5 Dex, +4 natural, -1 size","hp":67,"hd":"9d8+27","hdvalue":9,"fort":9,"ref":8,"will":4,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":40}],"melee":"longsword +10 (2d6+5/19-20) or   2 slams +10 (1d6+5)","ranged":"mwk composite longbow +9 (2d6+5/x3)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"},{"spell":"speak with animals"}]},{"frequency":"1/day","spells":[{"spell":"enlarge person","details":"self only"},{"spell":"spike growth"}]},{"frequency":"3/day","spells":[{"spell":"charm animal"},{"spell":"quench"},{"spell":"tree shape"}]}],"strength":20,"dexterity":21,"constitution":17,"intelligence":14,"wisdom":15,"charisma":12,"baseatk":6,"cmb":11,"cmd":24,"feats":[{"feat":"Deadly Aim"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+15 when jumping"},{"skill":"Climb","value":14},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":11},{"skill":"Profession (farmer)","value":8},{"skill":"Stealth","value":7,"special":"+11 in forests"},{"skill":"Survival","value":8}],"languages":["Common","Giant","Sylvan","speak with animals"],"environments":["temperate forests"],"organizations":["solitary","gang (2-4)","hunting party (5-9, plus 1-4 dire wolves)","clan (10-40, plus 35% noncombatants, 1-3 druids or witches of 2nd-4th level, 1 ranger chieftain of 3rd-7th level, 4-10 dire wolves, and 2-8 giant eagles)"],"treasure":"standard (leather armor, longsword, masterwork composite longbow with 20 arrows)","description_visual":"Standing tall and graceful, this sharp-eared giant's skin is pale. Its large brow gives it a somewhat primitive visage.","group":"Giant","source":"PFRPG Bestiary 2","description":"Wood giants are the wardens of the deepest, wildest portions of the world's forests. Unlike many of their kin, wood giants are slow to anger, peaceful, and artistic, and display an infinite patience in their duty. A wood giant's role is to preserve and protect the wilderness-a role they believe that nature itself granted them, the proof of which manifests in their magical abilities tied to the natural world.\n\nWood giant culture is as complex as their forest homes. Much of a tribe's time is spent tending to a forest's health: planting new trees, clearing away dead brush, and hunting abominations that pervert the natural order. Individuals may even cultivate their forest homes into elaborate demesnes, mazes, or living temples. They are an isolated race, only rarely meeting to trade with other tribes or the occasional elven settlement. While primarily good-natured, wood giants are distrustful of outsiders and prone to great melancholies.\n\nSmall clans claim enormous tracts of wooded land, but rarely build permanent homes. Members may spread out over their entire region by day only to gather and bed down, exposed to the elements, after sundown. In harsh weather, tribes cluster close together in the densest thickets with their backs turned outward.\n\nWood giants stand 14 ft. tall and weigh 1,200 pounds. They are vegetarians by choice, resorting to eating meat only when no other option is available.","ecology":"","habitat_society":""},{"name":"Wood Golem","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"construct","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":64,"hd":"8d10+20","hdvalue":8,"fort":2,"ref":5,"will":5,"dr":"5/adamantine","immunities":["construct traits","magic"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +12 (2d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"splintering"}],"strength":18,"dexterity":17,"wisdom":17,"charisma":1,"baseatk":8,"cmb":12,"cmd":25,"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"This human-sized automaton resembles a crude humanoid figure made of cast-off pieces of wood.","group":"Golem","source":"PFRPG Bestiary","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A wood golem is immune to any spell or spell-like ability that allows spell resistance, with the exception of spells and spell-like abilities that have the Fire descriptor, which affect it normally. In addition, certain spells and effects function differently against the creature, as noted below. • Warp wood or wood shape slows a wood golem (as the slow spell) for 2d6 rounds (no save). • Repel wood drives the golem back 60 ft. and deals 2d12 points of damage to it (no save). • A magical attack that deals cold damage breaks any slow effect on the golem and heals 1 point of damage for every 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A wood golem gets no saving throw against attacks that deal cold damage."},{"type":"Splintering","kind":"Su","details":"As a free action once every 1d4+1 rounds, a wood golem can launch a barrage of razor-sharp wooden splinters from its body in a 20-foot-radius burst. All creatures caught within this area take 6d6 points of slashing damage (Reflex DC 14 halves). The save DC is Constitution-based."}],"description":"A wood golem is carved from rare woods, assembled into a roughly humanoid body with articulated limbs. Their creators usually leave their bodies almost unfinished, with individual pieces of lumber and unworked wood apparent and obvious as part of their construction. A wood golem stands 6-1/2 ft. tall and weighs 400 pounds.\n\nConstruction The pieces of a wood golem are assembled from blocks of fine wood and sprinkled with rare powders and crushed herbs worth at least 300 gp.\n\nWood Golem CL 7th; Price 19,300 gp Construction Requirements Craft Construct, alarm, animate objects, cat's grace, geas/quest, limited wish, creator must be caster level 12th; Skill Craft (carpentry) DC 17; Cost 8,800 gp","ecology":"","habitat_society":""},{"name":"Woolly Rhinoceros","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"animal","init":0,"senses":[{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 natural, -1 size","hp":76,"hd":"8d8+40","hdvalue":8,"fort":13,"ref":6,"will":3,"speed":[{"type":"land","speed":30}],"melee":"gore +14 (2d8+13)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 4d8+18"},{"type":"trample","details":"2d6+13, DC 23"}],"strength":28,"dexterity":10,"constitution":21,"intelligence":2,"wisdom":13,"charisma":3,"baseatk":6,"cmb":16,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":15}],"environments":["cold plains"],"organizations":["solitary","pair","herd (3-12)"],"treasure":"none","description_visual":"This large rhinoceros has a shaggy pelt of long, brown fur and a row of immense horns on its snout and brow.","group":"Rhinoceros","source":"PFRPG Bestiary","description":"The woolly rhinoceros is an herbivore, though unlike its non-woolly cousin it grazes for food rather than browsing on larger plants. The woolly rhino is legendary for its foul temper, and its size and huge horn give it a ferocious bravery. Any threat (real or perceived) to the rhino or its herd is met with loud bellows and the stomping of ft. Often, those who unwittingly anger a woolly rhino have no time to amend the intrusion before the beast attacks.","ecology":"","habitat_society":""},{"name":"Wyrmling Red Dragon","cr":6,"xp":2400,"alignment":"CE","size":"Small","type":"dragon","subtypes":["fire"],"init":6,"senses":[{"type":"dragon senses"}],"ac":19,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+2 Dex, +6 natural, +1 size","hp":59,"hd":"7d12+14","hdvalue":7,"fort":7,"ref":7,"will":7,"immunities":["fire","paralysis","sleep"],"weaknesses":["Vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"average"}],"melee":"bite +11 (1d6+4), 2 claws +11 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. cone, DC 15, 2d10 fire"}],"strength":17,"dexterity":14,"constitution":15,"intelligence":10,"wisdom":11,"charisma":10,"baseatk":7,"cmb":9,"cmd":21,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Fly","value":14},{"skill":"Intimidate","value":10},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":16}],"languages":["Draconic"],"environments":["warm mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crown of cruel horns surrounds the head of this mighty dragon. Thick scales the color of molten rock cover its long body.","group":"Chromatic Dragon","source":"PFRPG Bestiary","description":"Few creatures are more cruel and fearsome than the mighty red dragon. King of the chromatics, this terrible beast brings ruin and death to the lands that fall under its shadow.","ecology":"","habitat_society":""}];
